const LEGAL={"en": {"privacy": {"title": "Privacy Policy", "s": [["Who we are", "Nurse Care is a platform that connects patients with independent licensed nurses for home care in Egypt. The operator is Mohamed Abou Bakr (\"we\"). Contact: {C}. By creating an account you agree to this policy."], ["Data we collect", "Account data: name, phone number, email address, password (kept by Firebase Authentication, not visible to us), national ID number and a photo of your national ID card. Nurses also provide a nursing license number and photos of their license and certificate. Request data: service, date, time, area, full address, notes, who provides medical supplies, price and visit confirmation status. These details can reveal information about your health, which is sensitive data. Technical data: your language choice and login session are stored on your device. Requests also include the medical supplies you ask the nurse to bring. You may also attach a photo of a prescription so the nurse knows which supplies to bring. Ratings and comments you give or receive, complaints you submit, and account status (such as blocks) are also stored. If you choose to share your location, we store its coordinates, and any map link you paste, with your request. After a nurse accepts a request, the nurse's live location is shared with the patient of that visit while the app is open, until the visit is completed or cancelled, and the last location is stored with the visit. If a service needs a doctor's order you may attach a photo of it; it is revealed only to the nurse whose offer you confirm."], ["Why we use it", "To verify identities and nurse licenses; to create your account; to match requests with nurses and let the matched parties contact each other; to calculate and track our commission; to prevent fraud and keep users safe; and to meet legal obligations. We do not sell your data and we do not use it for advertising."], ["Who can see it", "Your national ID number and your ID, license and certificate photos are visible only to you and the Nurse Care administrator. Open requests show verified nurses only the service, date, time, area, price and requested supplies. Your name, phone number, address and notes are revealed only to the nurse who accepts your request, and the nurse's name and phone number are revealed to the patient after acceptance. We may disclose data if required by law or by a competent authority. A prescription photo, if you attach one, is revealed only to the nurse who accepts your request. Your shared location is revealed only to the nurse who accepts your request. A nurse's live location is visible only to the patient of that visit and to the administrator. To match nearby nurses, verified nurses also see an approximate area (about 1 km) of the location you selected; the exact location is revealed only to the nurse who accepts. Star ratings given to a nurse (without the patient's name or comment) are visible to other signed-in users so patients can decide; comments stay private."], ["Service providers", "We use Google Firebase (authentication and database), GitHub Pages (hosting) and Google Fonts. Your data is processed on their infrastructure, which may be outside Egypt. By using the app you consent to this transfer. Maps are provided by OpenStreetMap: viewing a map or searching for a place sends the map area or search text to OpenStreetMap servers. If a nurse taps Navigate, Google Maps opens with the destination."], ["How long we keep it", "We keep your data while your account is active. If you delete your account, we close it and stop showing it in the app, but we keep your records for a limited period as needed for legal, safety, fraud-prevention, accounting and dispute-resolution purposes, after which they are deleted or anonymised. Contact {C} to ask about your data."], ["Security", "We use access rules so each user can only read the data they are entitled to, and the administrator verifies nurses before they can see requests. No system is completely secure, so keep your password private."], ["Your rights", "Under Egypt's Personal Data Protection Law (Law 151 of 2020) you may ask to access, correct or delete your data and withdraw your consent by contacting {C}. Withdrawing consent may prevent us from providing the service."], ["Children", "The service is for adults (18 and over). A minor patient must be represented by a parent or guardian who creates the account."], ["Changes", "We may update this policy. When it changes we will ask you to accept the new version."], ["Contact", "{C}"]]}, "terms": {"title": "Terms of Use", "s": [["About the service", "Nurse Care is a platform that connects patients with independent licensed nurses. Nurse Care does not provide medical care, does not employ nurses and does not control how services are delivered. Each nurse is an independent professional responsible for the care they provide."], ["Not for emergencies", "Nurse Care is not an emergency service and does not give medical advice. In an emergency call 123 for an ambulance."], ["Your account", "You must be 18 or older, give true and complete information including your real national ID number and photo, keep your password confidential and keep one account only. We may verify, refuse, suspend or close accounts that give false information or break these terms. Use a valid email address that you verify and a valid Egyptian mobile number. You may delete your account in the app."], ["Patients", "Describe your need accurately, including who provides the medical supplies. Make sure the visit location is safe and that a prescription or doctor's instructions are available when the service requires them. Confirm a visit only if it really took place. You can cancel a request until the nurse confirms the visit. If a nurse accepts your request but does not come, you can re-open the request two hours after the scheduled time slot ends. Nurses bring medical supplies only; medicines are bought by the patient from a licensed pharmacy. A nurse's acceptance is an offer: the visit starts only after you confirm the nurse. If no nurse accepts before the time slot ends, the request expires and you can choose a new time. Some services (IV cannula, IV fluids, injections into a vein, antibiotic injections, feeding tubes, urinary catheters, removal of stitches) need a doctor's order. You must attach it or confirm that you have it, and the nurse may refuse the visit if it cannot be shown."], ["Nurses", "You must hold a valid nursing license and give true documents. Perform only services within your license and training, follow doctors' orders, use sterile and safe practices and treat patients with respect and confidentiality. Use contact details and patient information only to carry out the requested visit. If you accept a request and do not perform the visit, the patient may re-open it two hours after the scheduled time slot ends; this is recorded on your account and repeated no-shows may lead to suspension. After accepting a request you must share your live location with the patient until the visit is completed. You may accept only requests within one hour of travel from the patient; your location when you accept is recorded with the request. When a request includes a doctor's order or a declaration, check it before starting; you may refuse a visit if no valid order is shown."], ["Prices and payment", "The app is free for patients. The price shown for each service is the amount the patient pays directly to the nurse, normally in cash after the visit, and may change. Medical supplies are agreed between patient and nurse when the nurse provides them."], ["Commission", "Nurse Care charges nurses a commission of {R}% of the listed price of each visit that both the nurse and the patient have confirmed. The nurse transfers it to Nurse Care as instructed in the app. Nurses who do not pay may be suspended. The rate may change with prior notice in the app."], ["Prohibited conduct", "Do not submit false documents or information, harass or endanger anyone, misuse other users' personal data, confirm visits that did not happen, or arrange visits outside the app with someone you met through it in order to avoid the commission. Ratings and complaints must be honest."], ["Blocking and complaints", "Nurse Care may warn, temporarily block or permanently block accounts that break these terms or put others at risk, and may cancel or re-open related requests. You can report a problem or complaint in the app and we will review it. Ratings are used to monitor quality and are visible to Nurse Care."], ["Liability", "To the maximum extent permitted by law, Nurse Care is not responsible for medical outcomes, the conduct of users or services provided by nurses. Nothing in these terms limits liability that cannot be limited under Egyptian law."], ["Privacy", "How we use your data is described in the Privacy Policy."], ["Changes", "We may update these terms. If we do, you will be asked to accept the new version to keep using the app."], ["Governing law", "These terms are governed by the laws of Egypt, and the competent Egyptian courts have jurisdiction."], ["Contact", "{C}"]]}}, "ar": {"privacy": {"title": "سياسة الخصوصية", "s": [["من نحن", "Nurse Care منصة تربط المرضى بممرضين مرخّصين ومستقلين لتقديم الرعاية المنزلية في مصر. المشغّل هو محمد أبو بكر («نحن»). للتواصل: {C}. بإنشاء حساب فأنت توافق على هذه السياسة."], ["البيانات التي نجمعها", "بيانات الحساب: الاسم ورقم الموبايل والبريد الإلكتروني وكلمة المرور (تُحفظ لدى Firebase Authentication ولا نراها) والرقم القومي وصورة البطاقة الشخصية. ويقدّم الممرضون أيضاً رقم رخصة التمريض وصورة الرخصة وصورة الشهادة. بيانات الطلبات: الخدمة والتاريخ والوقت والمنطقة والعنوان بالتفصيل والملاحظات وجهة توفير المستلزمات الطبية والسعر وحالة تأكيد الزيارة. وقد تكشف هذه التفاصيل معلومات عن صحتك، وهي بيانات حساسة. بيانات تقنية: اختيار اللغة وجلسة الدخول تُحفظ على جهازك. وتتضمن الطلبات أيضاً المستلزمات الطبية التي تطلب من الممرض إحضارها. ويمكنك أيضاً إرفاق صورة روشتة ليعرف الممرض المستلزمات المطلوب إحضارها. كما نحفظ التقييمات والتعليقات التي تعطيها أو تتلقاها، والشكاوى التي ترسلها، وحالة الحساب (مثل الحظر). وإذا اخترت مشاركة موقعك، نحفظ إحداثياته وأي لينك خريطة تلصقه مع طلبك. وبعد أن يقبل الممرض الطلب، يُشارَك موقعه المباشر مع مريض هذه الزيارة أثناء فتح التطبيق، إلى أن تكتمل الزيارة أو تُلغى، ويُحفظ آخر موقع مع الزيارة. وإذا كانت الخدمة تحتاج أمر طبيب فيمكنك إرفاق صورته، ولا تُكشف إلا للممرض الذي تؤكد عرضه."], ["لماذا نستخدمها", "للتحقق من الهويات وتراخيص الممرضين، وإنشاء حسابك، ومطابقة الطلبات مع الممرضين وتمكين الطرفين من التواصل، وحساب عمولتنا ومتابعتها، ومنع الاحتيال وحماية المستخدمين، والوفاء بالالتزامات القانونية. لا نبيع بياناتك ولا نستخدمها في الإعلانات."], ["من يستطيع رؤيتها", "الرقم القومي وصور البطاقة والرخصة والشهادة لا يراها إلا أنت ومدير Nurse Care. وتعرض الطلبات المفتوحة للممرضين الموثّقين الخدمة والتاريخ والوقت والمنطقة والسعر والمستلزمات المطلوبة فقط. أما اسمك ورقم موبايلك وعنوانك وملاحظاتك فلا تُكشف إلا للممرض الذي يقبل طلبك، ويُكشف اسم الممرض ورقمه للمريض بعد القبول. وقد نفصح عن البيانات إذا طلبت ذلك جهة مختصة أو اقتضى القانون. وصورة الروشتة، إن أرفقتها، لا تُكشف إلا للممرض الذي يقبل طلبك. وموقعك المشارَك لا يُكشف إلا للممرض الذي يقبل طلبك. والموقع المباشر للممرض لا يراه إلا مريض هذه الزيارة والمدير. ولمطابقة الممرضين القريبين، يرى الممرضون الموثّقون أيضاً منطقة تقريبية (حوالي 1 كم) للموقع الذي حدّدته، ولا يُكشف الموقع الدقيق إلا للممرض الذي يقبل. وتقييمات النجوم التي تُمنح للممرض (بدون اسم المريض أو تعليقه) تظهر للمستخدمين المسجلين الآخرين ليتمكن المرضى من القرار، أما التعليقات فتبقى خاصة."], ["مقدمو الخدمات التقنية", "نستخدم Google Firebase (المصادقة وقاعدة البيانات) وGitHub Pages (الاستضافة) وGoogle Fonts. تُعالج بياناتك على بنيتهم التحتية وقد تكون خارج مصر. باستخدامك التطبيق فأنت توافق على هذا النقل. والخرائط مقدّمة من OpenStreetMap: عرض الخريطة أو البحث عن مكان يرسل منطقة الخريطة أو نص البحث إلى خوادم OpenStreetMap. وإذا ضغط الممرض على الملاحة يُفتح Google Maps بالوجهة."], ["مدة الاحتفاظ", "نحتفظ ببياناتك طالما حسابك نشط. وإذا حذفت حسابك فإننا نغلقه ونتوقف عن إظهاره في التطبيق، لكننا نحتفظ بسجلاتك لفترة محدودة بحسب ما يلزم لأغراض قانونية وأمنية ومنع الاحتيال والمحاسبة وحل النزاعات، ثم تُحذف أو تُجهّل هويتها. للاستفسار عن بياناتك تواصل على {C}."], ["الأمان", "نستخدم قواعد وصول تمنع كل مستخدم من قراءة غير البيانات المسموح له بها، ويوثّق المدير الممرضين قبل أن يروا الطلبات. لا يوجد نظام آمن بالكامل، فحافظ على سرية كلمة مرورك."], ["حقوقك", "وفقاً لقانون حماية البيانات الشخصية المصري (القانون 151 لسنة 2020) يحق لك طلب الاطلاع على بياناتك أو تصحيحها أو حذفها وسحب موافقتك، بالتواصل على {C}. وقد يمنعنا سحب الموافقة من تقديم الخدمة."], ["الأطفال", "الخدمة للبالغين (18 سنة فأكثر). ويجب أن يمثّل المريض القاصر أحد والديه أو وصيّه الذي ينشئ الحساب."], ["التعديلات", "قد نحدّث هذه السياسة، وسنطلب منك الموافقة على النسخة الجديدة عند تغييرها."], ["التواصل", "{C}"]]}, "terms": {"title": "شروط الاستخدام", "s": [["عن الخدمة", "Nurse Care منصة تربط المرضى بممرضين مرخّصين ومستقلين. وهي لا تقدّم رعاية طبية ولا توظّف الممرضين ولا تتحكم في طريقة تقديم الخدمة. كل ممرض مهني مستقل ومسؤول عن الرعاية التي يقدّمها."], ["ليست للطوارئ", "Nurse Care ليست خدمة طوارئ ولا تقدّم نصيحة طبية. في الطوارئ اتصل بـ 123 للإسعاف."], ["حسابك", "يجب أن يكون عمرك 18 سنة فأكثر، وأن تقدّم معلومات صحيحة وكاملة تشمل رقمك القومي وصورة بطاقتك الحقيقيين، وأن تحافظ على سرية كلمة المرور، وأن يكون لك حساب واحد فقط. يحق لنا التحقق من الحسابات أو رفضها أو إيقافها أو إغلاقها إذا قدّمت معلومات كاذبة أو خالفت هذه الشروط. وأن يكون بريدك الإلكتروني صالحاً وتؤكده، ورقم موبايلك مصرياً صالحاً. ويمكنك حذف حسابك من داخل التطبيق."], ["المرضى", "صف احتياجك بدقة، بما في ذلك من يوفّر المستلزمات الطبية. تأكد من أن مكان الزيارة آمن، ومن توفر الروشتة أو تعليمات الطبيب عندما تتطلبها الخدمة. لا تؤكد زيارة إلا إذا تمّت فعلاً. يمكنك إلغاء الطلب إلى أن يؤكد الممرض الزيارة. إذا قبل ممرض طلبك ولم يحضر، يمكنك إعادة فتح الطلب بعد انتهاء الموعد المحدد بساعتين. يحضر الممرضون المستلزمات الطبية فقط، أما الأدوية فيشتريها المريض من صيدلية مرخّصة. قبول الممرض هو عرض: لا تبدأ الزيارة إلا بعد أن تؤكد الممرض. وإذا لم يقبل أي ممرض قبل انتهاء الفترة الزمنية ينتهي الطلب ويمكنك اختيار موعد جديد. وبعض الخدمات (الكانيولا والمحاليل والحقن الوريدية والمضاد الحيوي بالحقن ورايل التغذية والقسطرة البولية وإزالة الغرز) تحتاج إلى أمر طبيب، ويجب أن ترفقه أو تؤكد أنه موجود لديك، وللممرض أن يرفض الزيارة إذا تعذّر إبرازه."], ["الممرضون", "يجب أن تحمل رخصة تمريض سارية وتقدّم مستندات صحيحة. لا تقدّم إلا الخدمات التي تدخل في نطاق رخصتك وتدريبك، والتزم بتعليمات الطبيب، واتبع الممارسات المعقّمة والآمنة، وعامل المرضى باحترام وسرية. لا تستخدم بيانات الاتصال ومعلومات المريض إلا لتنفيذ الزيارة المطلوبة. إذا قبلت طلباً ولم تنفّذ الزيارة، يجوز للمريض إعادة فتح الطلب بعد انتهاء الموعد المحدد بساعتين، ويُسجَّل ذلك عليك، وقد يؤدي تكرار التخلّف إلى إيقاف حسابك. وبعد قبول الطلب يجب عليك مشاركة موقعك المباشر مع المريض إلى أن تكتمل الزيارة. ولا يجوز لك قبول إلا الطلبات التي تبعد عن المريض ساعة سفر على الأكثر، ويُسجَّل موقعك وقت القبول مع الطلب. وعندما يتضمن الطلب أمر طبيب أو إقراراً به، تحقق منه قبل البدء، ولك رفض الزيارة إذا لم يُبرَز أمر صحيح."], ["الأسعار والدفع", "التطبيق مجاني للمرضى. السعر المعروض لكل خدمة هو المبلغ الذي يدفعه المريض للممرض مباشرة، عادةً نقداً بعد الزيارة، وقد يتغير. أما المستلزمات الطبية فيتفق عليها المريض والممرض عندما يوفّرها الممرض."], ["العمولة", "تحصّل Nurse Care من الممرض عمولة قدرها {R}% من السعر المعروض لكل زيارة أكّدها الممرض والمريض معاً. ويحوّلها الممرض إلى Nurse Care وفق التعليمات داخل التطبيق. قد يتم إيقاف الممرضين الذين لا يسددون. وقد تتغير النسبة بإشعار مسبق داخل التطبيق."], ["السلوك المحظور", "لا تقدّم مستندات أو معلومات كاذبة، ولا تضايق أو تعرّض أحداً للخطر، ولا تسيء استخدام بيانات المستخدمين الآخرين، ولا تؤكد زيارات لم تتم، ولا تتفق على زيارات خارج التطبيق مع شخص تعرفت عليه من خلاله بغرض تجنّب العمولة. ويجب أن تكون التقييمات والشكاوى صادقة."], ["الحظر والشكاوى", "يحق لـ Nurse Care التحذير أو الحظر المؤقت أو الدائم للحسابات التي تخالف هذه الشروط أو تعرّض الآخرين للخطر، وإلغاء الطلبات المرتبطة أو إعادة فتحها. ويمكنك الإبلاغ عن مشكلة أو شكوى من داخل التطبيق وسنراجعها. وتُستخدم التقييمات لمراقبة الجودة وتظهر لـ Nurse Care."], ["المسؤولية", "إلى أقصى حد يسمح به القانون، لا تتحمل Nurse Care مسؤولية النتائج الطبية أو سلوك المستخدمين أو الخدمات التي يقدّمها الممرضون. ولا يقيّد أي بند هنا مسؤولية لا يجوز تقييدها بموجب القانون المصري."], ["الخصوصية", "يوضّح استخدامنا لبياناتك في سياسة الخصوصية."], ["التعديلات", "قد نحدّث هذه الشروط، وفي هذه الحالة سنطلب منك الموافقة على النسخة الجديدة لتواصل استخدام التطبيق."], ["القانون الواجب التطبيق", "تخضع هذه الشروط لقوانين جمهورية مصر العربية، وتختص المحاكم المصرية المختصة بالنظر في أي نزاع."], ["التواصل", "{C}"]]}}};
const RATE=0.10; // Nurse Care commission (10%)
const PAY_INFO='InstaPay: modemode1991@instapay'; // e.g. 'InstaPay: name@instapay' - shown to nurses who owe commission
const fee=r=>{const p=PRICES[r.service];return p?Math.round(p*RATE):0};
const pt=(k,l)=>PRICES[k]?`${PRICES[k]} ${l.egp}`:l.byCase;
const showP=r=>r.price?` · ${esc(r.price)} ${t('egp')}`:r.service==='bed'?` · ${t('byCase')}`:'';
let L=(()=>{try{return localStorage.getItem('nc-l')}catch(e){}})()||((navigator.language||'').startsWith('ar')?'ar':'en');
const t=k=>T[L][k]??esc(k),$=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
